#include <vector>
#include <deque>

class Solution {
public:
    int maxAcceptedRequests(std::vector<int>& requests, int w, int limit) {
        std::deque<int> q;
        int accepted = 0;
        for (int t : requests) {
            while (!q.empty() && q.front() <= t - w) q.pop_front();
            if ((int)q.size() < limit) {
                q.push_back(t);
                accepted++;
            }
        }
        return accepted;
    }
};

import java.util.*;

class Solution {
    public int maxAcceptedRequests(int[] requests, int w, int limit) {
        ArrayDeque<Integer> q = new ArrayDeque<>();
        int accepted = 0;
        for (int t : requests) {
            while (!q.isEmpty() && q.peekFirst() <= t - w) q.pollFirst();
            if (q.size() < limit) {
                q.addLast(t);
                accepted++;
            }
        }
        return accepted;
    }
}

function maxAcceptedRequests(requests, w, limit) {
